// Hosted-demo seeding + reset helpers (standalone offline entry only).
//
// The published docs site ships the full app in offline mode at
// /diorama/demo/, preloaded with the committed demo floorplans as selectable
// configurations. This module is the DOM-free core of that boot: seed the
// demo envelopes as configs (idempotent), switch to the requested one, and
// enumerate the localStorage keys "Reset demo" clears. app.ts wires it up.
//
// Pure config-layer only — imports the Planner as a TYPE, never three.js, so
// it stays out of the lazy renderer chunk and the startup bundle's 3D split.
// NEVER runs in panel mode (panel.ts adopts a Planner; no demo path there).

import type { Planner } from './planner.js';
import type { Floor, FurnitureKind, LightIconKind, Store } from './types.js';
import { defaultStore, repairFloor } from './storage.js';
import { FURNITURE_KINDS } from './geometry.js';
import { withDemoFlightsEnvelope } from './flights.js';

export interface DemoManifestEntry { slug: string; name: string; }
export interface DemoSeedResult {
  seeded: string[];         // slugs newly imported this call
  activeId: string | null;  // active config after the switch
  requested: string | null; // the slug we tried to open
}

// localStorage marker: set to demoSeedHash(manifest) once a build's homes are
// seeded. A matching value means "already seeded this build" → skip re-import
// (so a visitor's own edits / deletions stick); a new build with more homes
// changes the hash → the missing ones seed on next load. "Reset demo" removes it.
export const DEMO_SEEDED_KEY = 'diorama:demo:seeded';

// Keys "Reset demo" wipes: the config registry mirror + active-body cache +
// every offline user_data slot (diorama:local:*) + the seeded marker. Anything
// else in localStorage (view pref, sidebar-collapsed, offline flag, unrelated
// apps) is deliberately LEFT ALONE.
const RESET_EXACT = ['diorama:configs', 'diorama:store:v1', DEMO_SEEDED_KEY];
const RESET_PREFIXES = ['diorama:local:'];

// Stable hash of a manifest's NAME SET (order-independent). Bumps when the set
// of demo homes changes so a fresh build re-seeds the newcomers.
export function demoSeedHash(manifest: DemoManifestEntry[]): string {
  const names = manifest.map(m => m.name).sort();
  const s = names.join('\0');
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;  // djb2
  return (h >>> 0).toString(36) + '.' + names.length;
}

// Seed the demo envelopes as configs (idempotent by NAME), then switch to the
// requested slug's config (unknown/absent slug → the first manifest entry).
// `envelopes` maps slug → the export envelope (object or JSON string); an entry
// whose config already exists (or whose envelope is missing) is skipped, so a
// re-run never duplicates and passing {} makes this a pure switch. importConfig
// requires edit mode — the offline demo defaults to edit, and this never runs
// in kiosk/view (URL mode is applied AFTER seeding). Never throws.
export async function seedDemoConfigs(
  planner: Planner,
  manifest: DemoManifestEntry[],
  envelopes: Record<string, unknown>,
  requestedSlug?: string | null,
): Promise<DemoSeedResult> {
  const seeded: string[] = [];
  for (const entry of manifest) {
    if (!entry || !entry.slug || !entry.name) continue;
    if (planner.listConfigs().some(c => c.name === entry.name)) continue;  // idempotent
    const env = envelopes[entry.slug];
    if (env == null) continue;
    try {
      // Switch on the SYNTHETIC flight source as the envelope goes in. The
      // committed floorplans are generated and carry no `flights` block, and
      // every fetched source needs a Home Assistant the hosted demo does not
      // have — so without this the published showcase has an empty sky. Pure,
      // text-in/text-out, and a no-op on anything that already authored the
      // block or is not parseable (see withDemoFlightsEnvelope).
      const text = withDemoFlightsEnvelope(
        typeof env === 'string' ? env : JSON.stringify(env));
      const res = await planner.importConfig(text, entry.name);
      if (res.ok) seeded.push(entry.slug);
      else console.warn('[diorama demo] import failed for', entry.slug, res.error);
    } catch (err) {
      console.warn('[diorama demo] import threw for', entry.slug, err);
    }
  }
  // Resolve requested slug → manifest name → config; fall back to the first home.
  let targetName: string | undefined;
  if (requestedSlug) targetName = manifest.find(m => m.slug === requestedSlug)?.name;
  if (!targetName) targetName = manifest[0]?.name;
  if (targetName) {
    const cfg = planner.listConfigs().find(c => c.name === targetName);
    if (cfg && cfg.id !== planner.activeConfigId) {
      try { await planner.switchConfig(cfg.id); }
      catch (err) { console.warn('[diorama demo] switch failed:', err); }
    }
  }
  return { seeded, activeId: planner.activeConfigId ?? null, requested: requestedSlug ?? null };
}

// Minimal Storage surface used for reset enumeration (Web Storage or a fake).
interface KeyedStorage {
  length: number;
  key(i: number): string | null;
  removeItem(k: string): void;
}

// Enumerate (never mutate) the localStorage keys "Reset demo" should remove.
export function demoResetKeys(storage: KeyedStorage): string[] {
  const out: string[] = [];
  try {
    for (let i = 0; i < storage.length; i++) {
      const k = storage.key(i);
      if (k == null) continue;
      if (RESET_EXACT.includes(k) || RESET_PREFIXES.some(p => k.startsWith(p))) out.push(k);
    }
  } catch { /* storage unavailable */ }
  return out;
}

// Remove exactly the demo keys. Enumerate first (removing while iterating an
// index-keyed Storage shifts indices), then delete.
export function clearDemoStorage(storage: KeyedStorage): void {
  for (const k of demoResetKeys(storage)) {
    try { storage.removeItem(k); } catch { /* ignore */ }
  }
}

// ── Single-model viewer (?model=<kind>) ────────────────────────────────────────
// A ?model= visit opens ONE model in a small scratch floor instead of a whole
// house. The gallery's "View in demo" tiles deep-link here. Reuses the offline
// config layer: a single reusable config named "Model viewer" is upserted (never
// spammed) and switched to; app.ts then frames it in 3D with the returned cam.

export const MODEL_VIEWER_NAME = 'Model viewer';

// The LightIconKind union (types.ts) as a runtime lookup — a ?model=<kind> is a
// light icon kind when it lands here (else FURNITURE_KINDS, else unknown). Kept
// in sync with the union by hand (there is no exported runtime table).
const LIGHT_ICON_KINDS = new Set<string>([
  'bulb', 'spot', 'pendant', 'sconce', 'strip', 'fireplace', 'lamp', 'bowl',
  'tiered', 'round', 'recessed', 'jar', 'oval', 'fan', 'fan_light', 'string',
  'under_cabinet', 'wall_sconce', 'step', 'flood', 'inground', 'ground_spot',
  'heatlamp', 'exhaust', 'exhaust_wall', 'exhaust_light',
]);

export interface ModelKindInfo { isFurniture: boolean; isLight: boolean; }

// Which table a ?model=<kind> belongs to. Furniture wins if a kind is somehow in
// both (they never overlap today). Neither → unknown (caller falls back to demo).
export function classifyModelKind(kind: string): ModelKindInfo {
  const isFurniture = Object.prototype.hasOwnProperty.call(FURNITURE_KINDS, kind);
  return { isFurniture, isLight: !isFurniture && LIGHT_ICON_KINDS.has(kind) };
}

export interface ModelViewerResult {
  ok: boolean;       // false → unknown kind; caller should fall back to plain demo
  kind: string;
  isLight: boolean;  // true = placed as a light fixture; false = furniture piece
  cam?: number[];    // [px,py,pz, tx,ty,tz] dimetric "sims" pose for the floor
}

// A dimetric/"sims" camera framing a floor centred at the scene origin, matching
// three-renderer applyViewPreset('sims'): azimuth 45°, elevation atan(1/√2), a
// pull-back scaled to the larger footprint dimension. Same math as the docs
// floor-plan capture's isoCam, kept here so the pure module owns it.
function simsCam(fw: number, fd: number): number[] {
  const dist = Math.max(fw, fd) * 1.35;
  const el = Math.atan(1 / Math.SQRT2);
  const r = dist * Math.cos(el), h = dist * Math.sin(el);
  const a = Math.PI / 4, ty = 600;
  return [-r * Math.sin(a), ty + h, -r * Math.cos(a), 0, ty, 0].map(v => Math.round(v));
}

// Build a complete scratch store: one small floor with the single requested model
// centred. repairFloor backfills every array so the store is renderer-safe whether
// it flows through importConfig (fresh) or a direct floor swap (reuse).
function buildModelStore(kind: string, isLight: boolean): Store {
  const w = 6000, d = 5000, cx = w / 2, cy = d / 2;
  const floor: Floor = repairFloor({ id: 'mv', name: 'Model', w, d });
  if (isLight) {
    floor.lights = [{ id: 'mv_light', x: cx, y: cy, entity_id: null,
                      localState: 'on', iconKind: kind as LightIconKind }];
  } else {
    const def = FURNITURE_KINDS[kind as FurnitureKind];
    floor.furniture = [{ id: 'mv_piece', x: cx, y: cy, w: def.w, h: def.h,
                         kind: kind as FurnitureKind, rotation: 0 }];
  }
  const store = defaultStore();
  store.floors = [floor];
  store.currentFloorId = 'mv';
  return store;
}

// Upsert the "Model viewer" config holding ONE instance of `kind` centred, switch
// to it, and return the dimetric cam app.ts should apply. Reused across ?model=
// visits: if the config already exists its floor content is REPLACED in place
// (never a new config per visit). Unknown kind → {ok:false} (no store change).
// Requires edit mode (the offline demo defaults to edit); never throws.
export async function seedModelViewer(planner: Planner, kind: string): Promise<ModelViewerResult> {
  const info = classifyModelKind(kind);
  if (!info.isFurniture && !info.isLight) return { ok: false, kind, isLight: false };
  const store = buildModelStore(kind, info.isLight);
  const existing = planner.listConfigs().find(c => c.name === MODEL_VIEWER_NAME);
  try {
    if (existing) {
      if (existing.id !== planner.activeConfigId) await planner.switchConfig(existing.id);
      // Replace the floor content in place (reuse — no config spam). The store is
      // fully repaired, so a direct swap is renderer-safe.
      planner.store.floors = store.floors;
      planner.store.currentFloorId = store.currentFloorId;
      planner.viewCenter = null; planner.zoom = 1;
      await planner.saveConfigNow();
      planner.emitConfig();
    } else {
      const env = { diorama: 2, name: MODEL_VIEWER_NAME, store };
      await planner.importConfig(JSON.stringify(env), MODEL_VIEWER_NAME);
    }
  } catch (err) {
    console.warn('[diorama demo] model viewer seed failed:', err);
  }
  return { ok: true, kind, isLight: info.isLight, cam: simsCam(store.floors[0].w, store.floors[0].d) };
}
